INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5456385, 786286, 63716, '<td valign="top">North Shore City - Kiwi entry (-: Nice work in that it interprets the theme but doesn''t seem to be especially eye-catching (not to me anyway!)</td>', 'North Shore City - Kiwi entry (-: Nice work in that it interprets the theme but doesn''t seem to be especially eye-catching (not to me anyway!)', '2009-04-29 01:22:45.000000', NULL, 1),
(5456389, 785680, 63716, '<td valign="top">I am struggling to see how this interprets the "reduce/re-us/recycle" theme. Maybe I''m just not looking at it right :(</td>', 'I am struggling to see how this interprets the "reduce/re-us/recycle" theme. Maybe I''m just not looking at it right :(', '2009-04-29 01:23:35.000000', NULL, 1),
(5456421, 785833, 93478, '<td valign="top">Excellent, very funny.  A green cape would have been better.  Very creative and good composition.  The focus is a little soft and the line in the back is not quite horizontal.  A seamless background would probably help.</td>', 'Excellent, very funny.  A green cape would have been better.  Very creative and good composition.  The focus is a little soft and the line in the back is not quite horizontal.  A seamless background would probably help.', '2009-04-29 01:31:23.000000', NULL, 1),
(5456455, 785304, 96751, '<td valign="top">Great concept, though there seems to be a lack of detail in the flower, and the reflection on the bulb, though in focus, looks blurred.</td>', 'Great concept, though there seems to be a lack of detail in the flower, and the reflection on the bulb, though in focus, looks blurred.', '2009-04-29 01:41:34.000000', NULL, 1),
(5456457, 784993, 96751, '<td valign="top">Viva Mexico.  Achoo!</td>', 'Viva Mexico.  Achoo!', '2009-04-29 01:42:02.000000', NULL, 1),
(5456459, 785512, 96751, '<td valign="top">Fun shot.  Could have used a bit more styling.</td>', 'Fun shot.  Could have used a bit more styling.', '2009-04-29 01:42:35.000000', NULL, 1),
(5456462, 785468, 96751, '<td valign="top">Very creative.  Very time consuming.  I wish the foreground objects had been either better lit or not included at all.</td>', 'Very creative.  Very time consuming.  I wish the foreground objects had been either better lit or not included at all.', '2009-04-29 01:43:25.000000', NULL, 1),
(5456465, 785911, 96751, '<td valign="top">Nice dof!</td>', 'Nice dof!', '2009-04-29 01:43:40.000000', NULL, 1),
(5456474, 786022, 96751, '<td valign="top">Great dof and bokeh.  Nice concept.</td>', 'Great dof and bokeh.  Nice concept.', '2009-04-29 01:45:42.000000', NULL, 1),
(5456480, 786281, 96751, '<td valign="top">Lovely concept, but a light in the left foreground would have vastly improved this shot.</td>', 'Lovely concept, but a light in the left foreground would have vastly improved this shot.', '2009-04-29 01:46:44.000000', NULL, 1),
(5456494, 785000, 96751, '<td valign="top">Nice post treatment - the "noise" is actually artistic.</td>', 'Nice post treatment - the "noise" is actually artistic.', '2009-04-29 01:50:39.000000', NULL, 1),
(5456497, 785254, 96751, '<td valign="top">Great lines!  Soothing colors.</td>', 'Great lines!  Soothing colors.', '2009-04-29 01:51:15.000000', NULL, 1),
(5456498, 786211, 96751, '<td valign="top">Hoover?  Great shot.  Amazing place.</td>', 'Hoover?  Great shot.  Amazing place.', '2009-04-29 01:51:47.000000', NULL, 1),
(5456500, 785685, 96751, '<td valign="top">Amazing colors!</td>', 'Amazing colors!', '2009-04-29 01:52:01.000000', NULL, 1),
